        public static readonly IReadOnlyList<Trade> List =
        [
            new("trade-solar", "☀️", "sun",
                Txt.Of("Solar energy|Energía solar|Énergie solaire|Energia solar"),
                Txt.Of("How solar panels turn light into electricity, how much they produce, how to place them and how to store the energy.|Cómo convierten la luz en electricidad los paneles solares, cuánto producen, cómo colocarlos y cómo guardar la energía.|Comment les panneaux solaires transforment la lumière en électricité, combien ils produisent, comment les placer et comment stocker l'énergie.|Com converteixen la llum en electricitat les plaques solars, quant produeixen, com col·locar-les i com guardar l'energia."),
                Txt.Of("Theory only. Installing panels on a roof and connecting them to the home is work for an authorised installer.|Solo teoría. Instalar paneles en un tejado y conectarlos a la casa es trabajo de un instalador autorizado.|Théorie uniquement. Poser des panneaux sur un toit et les raccorder à la maison est le travail d'un installateur agréé.|Només teoria. Instal·lar plaques en una teulada i connectar-les a la casa és feina d'un instal·lador autoritzat."),
                [
                    C("pv", "From light to electricity|De la luz a la electricidad|De la lumière à l'électricité|De la llum a l'electricitat", "In a photovoltaic cell, light frees electrons in silicon and creates a direct current (DC); the inverter changes it into the alternating current (AC) of the home.|En una célula fotovoltaica, la luz libera electrones en el silicio y crea una corriente continua; el inversor la convierte en la corriente alterna de la casa.|Dans une cellule photovoltaïque, la lumière libère des électrons dans le silicium et crée un courant continu ; l'onduleur le transforme en courant alternatif de la maison.|En una cèl·lula fotovoltaica, la llum allibera electrons en el silici i crea un corrent continu; l'inversor el converteix en el corrent altern de la casa.", Area.Physics, "Physics: the photovoltaic effect|Física: el efecto fotovoltaico|Physique : l'effet photovoltaïque|Física: l'efecte fotovoltaic"),
                    C("production", "How much a panel produces|Cuánto produce un panel|Combien produit un panneau|Quant produeix una placa", "Energy = power × hours of full sun. A 400 W panel with 5 hours of full sun gives about 2 kWh a day; it produces less with clouds, heat or dirt.|Energía = potencia × horas de sol pleno. Un panel de 400 W con 5 horas de sol pleno da unos 2 kWh al día; produce menos con nubes, calor o suciedad.|Énergie = puissance × heures de plein soleil. Un panneau de 400 W avec 5 heures de plein soleil donne environ 2 kWh par jour ; il produit moins avec des nuages, de la chaleur ou de la saleté.|Energia = potència × hores de sol ple. Una placa de 400 W amb 5 hores de sol ple dona uns 2 kWh al dia; produeix menys amb núvols, calor o brutícia.", Area.Mathematics, "Mathematics: power, time and energy|Matemáticas: potencia, tiempo y energía|Mathématiques : puissance, temps et énergie|Matemàtiques: potència, temps i energia", "pv"),
                    C("placement", "Orientation and tilt|Orientación e inclinación|Orientation et inclinaison|Orientació i inclinació", "In the northern hemisphere panels face south; a tilt close to the latitude works well all year; any shade on a panel lowers the whole string.|En el hemisferio norte los paneles miran al sur; una inclinación parecida a la latitud funciona bien todo el año; cualquier sombra sobre un panel baja toda la serie.|Dans l'hémisphère nord, les panneaux sont orientés au sud ; une inclinaison proche de la latitude marche bien toute l'année ; toute ombre sur un panneau fait baisser toute la série.|A l'hemisferi nord les plaques miren al sud; una inclinació semblant a la latitud funciona bé tot l'any; qualsevol ombra sobre una placa abaixa tota la sèrie.", Area.Geography, "Geography: latitude and the path of the Sun|Geografía: la latitud y el recorrido del Sol|Géographie : la latitude et la course du Soleil|Geografia: la latitud i el recorregut del Sol", "production"),
                    C("storage", "Batteries and self-consumption|Baterías y autoconsumo|Batteries et autoconsommation|Bateries i autoconsum", "Panels produce at midday; using the energy when it is produced (washing machine at noon) or storing it in a battery (kWh) avoids buying it at night.|Los paneles producen a mediodía; usar la energía cuando se produce (lavadora al mediodía) o guardarla en una batería (kWh) evita comprarla por la noche.|Les panneaux produisent à midi ; utiliser l'énergie quand elle est produite (machine à laver à midi) ou la stocker dans une batterie (kWh) évite de l'acheter la nuit.|Les plaques produeixen al migdia; fer servir l'energia quan es produeix (rentadora al migdia) o guardar-la en una bateria (kWh) evita comprar-la de nit.", Area.Chemistry, "Chemistry: how a battery stores energy|Química: cómo guarda energía una batería|Chimie : comment une batterie stocke l'énergie|Química: com guarda energia una bateria", "production"),
                    C("savings", "Savings and the environment|Ahorro y medio ambiente|Économies et environnement|Estalvi i medi ambient", "Payback time = cost ÷ savings per year. Solar electricity emits no CO₂ while it works, and panels last about 25 years.|Tiempo de amortización = coste ÷ ahorro al año. La electricidad solar no emite CO₂ mientras funciona y los paneles duran unos 25 años.|Temps de retour = coût ÷ économies par an. L'électricité solaire n'émet pas de CO₂ en fonctionnant, et les panneaux durent environ 25 ans.|Temps d'amortització = cost ÷ estalvi a l'any. L'electricitat solar no emet CO₂ mentre funciona i les plaques duren uns 25 anys.", Area.Economics, "Economics: investment and payback|Economía: inversión y amortización|Économie : investissement et retour|Economia: inversió i amortització", "storage"),
                ],
                [
                    Q("pv", 1, "What does a solar panel turn into electricity?|¿Qué convierte en electricidad un panel solar?|Qu'est-ce qu'un panneau solaire transforme en électricité ?|Què converteix en electricitat una placa solar?", "Light|La luz|La lumière|La llum", "Light frees electrons in the silicon of the cells.|La luz libera electrones en el silicio de las células.|La lumière libère des électrons dans le silicium des cellules.|La llum allibera electrons en el silici de les cèl·lules.", "Wind|El viento|Le vent|El vent", "Rain|La lluvia|La pluie|La pluja", "Sound|El sonido|Le son|El so"),
                    Q("pv", 2, "Which material are most solar cells made of?|¿De qué material son la mayoría de las células solares?|En quel matériau sont faites la plupart des cellules solaires ?|De quin material són la majoria de cèl·lules solars?", "Silicon|Silicio|Silicium|Silici", "Silicon is a semiconductor, made from very pure sand.|El silicio es un semiconductor que se obtiene de arena muy pura.|Le silicium est un semi-conducteur fabriqué à partir de sable très pur.|El silici és un semiconductor que s'obté de sorra molt pura.", "Copper|Cobre|Cuivre|Coure", "Plastic|Plástico|Plastique|Plàstic", "Gold|Oro|Or|Or"),
                    Q("pv", 3, "What is the inverter of a solar installation for?|¿Para qué sirve el inversor de una instalación solar?|À quoi sert l'onduleur d'une installation solaire ?|Per a què serveix l'inversor d'una instal·lació solar?", "It turns direct current into alternating current|Convierte la corriente continua en alterna|Il transforme le courant continu en alternatif|Converteix el corrent continu en altern", "Panels give DC; sockets and appliances use AC at 230 V.|Los paneles dan corriente continua; los enchufes usan alterna a 230 V.|Les panneaux donnent du continu ; les prises utilisent de l'alternatif à 230 V.|Les plaques donen corrent continu; els endolls fan servir altern a 230 V.", "It cleans the panels|Limpia los paneles|Il nettoie les panneaux|Neteja les plaques", "It turns the panels towards the Sun|Gira los paneles hacia el Sol|Il tourne les panneaux vers le Soleil|Gira les plaques cap al Sol", "It stores heat|Guarda calor|Il stocke la chaleur|Guarda calor"),
                    Q("production", 1, "A 400 W panel gets 5 hours of full sun. How much energy does it produce that day?|Un panel de 400 W recibe 5 horas de sol pleno. ¿Cuánta energía produce ese día?|Un panneau de 400 W reçoit 5 heures de plein soleil. Combien d'énergie produit-il ce jour-là ?|Una placa de 400 W rep 5 hores de sol ple. Quanta energia produeix aquell dia?", "2 kWh", "400 W × 5 h = 2,000 Wh = 2 kWh.|400 W × 5 h = 2000 Wh = 2 kWh.|400 W × 5 h = 2 000 Wh = 2 kWh.|400 W × 5 h = 2.000 Wh = 2 kWh.", "20 kWh", "405 kWh", "0.08 kWh|0,08 kWh|0,08 kWh|0,08 kWh"),
                    Q("production", 2, "Does a solar panel produce electricity on a cloudy day?|¿Produce electricidad un panel solar en un día nublado?|Un panneau solaire produit-il de l'électricité par temps nuageux ?|Produeix electricitat una placa solar en un dia ennuvolat?", "Yes, but much less|Sí, pero mucho menos|Oui, mais beaucoup moins|Sí, però molt menys", "Diffuse light still reaches it, often a fraction of a sunny day.|Le sigue llegando luz difusa, a menudo una fracción de la de un día de sol.|Il reçoit encore de la lumière diffuse, souvent une fraction de celle d'un jour ensoleillé.|Encara li arriba llum difusa, sovint una fracció de la d'un dia de sol.", "No, nothing at all|No, nada|Non, rien du tout|No, gens", "More than on a sunny day|Más que un día de sol|Plus qu'un jour de soleil|Més que un dia de sol", "Only at night|Solo de noche|Seulement la nuit|Només de nit"),
                    Q("production", 3, "Why do panels produce a little less on very hot days?|¿Por qué los paneles producen algo menos en los días muy calurosos?|Pourquoi les panneaux produisent-ils un peu moins les jours très chauds ?|Per què les plaques produeixen una mica menys els dies molt calorosos?", "The efficiency of the cells drops when they heat up|El rendimiento de las células baja cuando se calientan|Le rendement des cellules baisse quand elles chauffent|El rendiment de les cèl·lules baixa quan s'escalfen", "Panels like a lot of light but cool temperatures.|A los paneles les va bien mucha luz pero temperaturas frescas.|Les panneaux aiment beaucoup de lumière mais des températures fraîches.|A les plaques els va bé molta llum però temperatures fresques.", "The sun is weaker in summer|El sol es más débil en verano|Le soleil est plus faible en été|El sol és més feble a l'estiu", "Heat melts the silicon|El calor derrite el silicio|La chaleur fait fondre le silicium|La calor fon el silici", "It is not true|No es cierto|C'est faux|No és cert"),
                    Q("placement", 1, "In Spain or France, which way should solar panels face?|En España o Francia, ¿hacia dónde deben mirar los paneles solares?|En Espagne ou en France, vers où doivent être orientés les panneaux solaires ?|A Espanya o França, cap a on han de mirar les plaques solars?", "South|Al sur|Au sud|Al sud", "In the northern hemisphere the Sun crosses the southern sky.|En el hemisferio norte el Sol cruza el cielo por el sur.|Dans l'hémisphère nord, le Soleil traverse le ciel côté sud.|A l'hemisferi nord el Sol travessa el cel pel sud.", "North|Al norte|Au nord|Al nord", "Straight up only|Solo hacia arriba|Seulement vers le haut|Només cap amunt", "It does not matter|Da igual|Peu importe|Tant és"),
                    Q("placement", 2, "A tree shades one panel of a series. What happens?|Un árbol da sombra a un panel de una serie. ¿Qué pasa?|Un arbre fait de l'ombre sur un panneau d'une série. Que se passe-t-il ?|Un arbre fa ombra a una placa d'una sèrie. Què passa?", "The production of the whole series drops|Baja la producción de toda la serie|La production de toute la série baisse|Baixa la producció de tota la sèrie", "In series the current is limited by the weakest panel (optimisers reduce this).|En serie la corriente la limita el panel más débil (los optimizadores lo reducen).|En série, le courant est limité par le panneau le plus faible (les optimiseurs réduisent ce problème).|En sèrie el corrent el limita la placa més feble (els optimitzadors ho redueixen).", "Only that panel stops, nothing else|Solo se para ese panel, nada más|Seul ce panneau s'arrête, rien d'autre|Només s'atura aquella placa, res més", "The others produce more|Los demás producen más|Les autres produisent plus|Les altres produeixen més", "Nothing|Nada|Rien|Res"),
                    Q("placement", 3, "For good production all year, a fixed panel is usually tilted at an angle close to…|Para producir bien todo el año, un panel fijo se suele inclinar con un ángulo parecido a…|Pour bien produire toute l'année, un panneau fixe est souvent incliné d'un angle proche de…|Per produir bé tot l'any, una placa fixa se sol inclinar amb un angle semblant a…", "the latitude of the place|la latitud del lugar|la latitude du lieu|la latitud del lloc", "In Madrid (40° N) about 30–40°; flatter favours summer, steeper favours winter.|En Madrid (40° N) unos 30–40°; más plano favorece el verano y más inclinado el invierno.|À Madrid (40° N) environ 30–40° ; plus à plat favorise l'été, plus incliné favorise l'hiver.|A Madrid (40° N) uns 30–40°; més pla afavoreix l'estiu i més inclinat l'hivern.", "0°, always flat|0°, siempre plano|0°, toujours à plat|0°, sempre pla", "90°, vertical|90°, vertical|90°, vertical|90°, vertical", "the time of day|la hora del día|l'heure de la journée|l'hora del dia"),
                    Q("storage", 1, "When do home solar panels produce the most?|¿Cuándo producen más los paneles solares de una casa?|Quand les panneaux solaires d'une maison produisent-ils le plus ?|Quan produeixen més les plaques solars d'una casa?", "Around midday|Hacia mediodía|Vers midi|Cap al migdia", "The Sun is highest and its light crosses less atmosphere.|El Sol está más alto y su luz atraviesa menos atmósfera.|Le Soleil est le plus haut et sa lumière traverse moins d'atmosphère.|El Sol és més alt i la seva llum travessa menys atmosfera.", "At night|De noche|La nuit|De nit", "At dawn|Al amanecer|À l'aube|A l'alba", "Always the same|Siempre igual|Toujours pareil|Sempre igual"),
                    Q("storage", 2, "To use more of your own solar energy without a battery, it is better to…|Para aprovechar más tu energía solar sin batería, es mejor…|Pour utiliser davantage ton énergie solaire sans batterie, il vaut mieux…|Per aprofitar més la teva energia solar sense bateria, és millor…", "run the washing machine around midday|poner la lavadora hacia mediodía|lancer la machine à laver vers midi|posar la rentadora cap al migdia", "Using energy while it is produced is self-consumption: you buy less from the grid.|Usar la energía mientras se produce es autoconsumo: compras menos a la red.|Utiliser l'énergie quand elle est produite, c'est l'autoconsommation : tu achètes moins au réseau.|Fer servir l'energia mentre es produeix és autoconsum: compres menys a la xarxa.", "run it at midnight|ponerla a medianoche|la lancer à minuit|posar-la a mitjanit", "unplug the fridge|desenchufar la nevera|débrancher le frigo|desendollar la nevera", "cover the panels|tapar los paneles|couvrir les panneaux|tapar les plaques"),
                    Q("storage", 3, "In which unit is the capacity of a home battery given?|¿En qué unidad se da la capacidad de una batería doméstica?|Dans quelle unité donne-t-on la capacité d'une batterie domestique ?|En quina unitat es dona la capacitat d'una bateria domèstica?", "kWh (energy)|kWh (energía)|kWh (énergie)|kWh (energia)", "A 10 kWh battery can give 1 kW for about 10 hours.|Una batería de 10 kWh puede dar 1 kW durante unas 10 horas.|Une batterie de 10 kWh peut fournir 1 kW pendant environ 10 heures.|Una bateria de 10 kWh pot donar 1 kW durant unes 10 hores.", "Volts only|Solo voltios|Seulement des volts|Només volts", "Degrees|Grados|Degrés|Graus", "Litres|Litros|Litres|Litres"),
                    Q("savings", 1, "While it is working, how much CO₂ does a solar panel emit?|Mientras funciona, ¿cuánto CO₂ emite un panel solar?|Pendant qu'il fonctionne, combien de CO₂ émet un panneau solaire ?|Mentre funciona, quant de CO₂ emet una placa solar?", "None|Nada|Aucun|Gens", "It burns nothing; CO₂ is emitted only when it is manufactured and transported.|No quema nada; el CO₂ se emite solo al fabricarlo y transportarlo.|Il ne brûle rien ; le CO₂ n'est émis qu'à la fabrication et au transport.|No crema res; el CO₂ només s'emet en fabricar-la i transportar-la.", "The same as a car|Lo mismo que un coche|Autant qu'une voiture|El mateix que un cotxe", "More than a gas boiler|Más que una caldera de gas|Plus qu'une chaudière à gaz|Més que una caldera de gas", "Only at night|Solo de noche|Seulement la nuit|Només de nit"),
                    Q("savings", 2, "An installation costs 5,000 € and saves 625 € a year. How many years until it pays for itself?|Una instalación cuesta 5000 € y ahorra 625 € al año. ¿En cuántos años se amortiza?|Une installation coûte 5 000 € et fait économiser 625 € par an. En combien d'années est-elle remboursée ?|Una instal·lació costa 5.000 € i estalvia 625 € l'any. En quants anys s'amortitza?", "8 years|8 años|8 ans|8 anys", "5,000 ÷ 625 = 8 years; then it keeps saving.|5000 ÷ 625 = 8 años; después sigue ahorrando.|5 000 ÷ 625 = 8 ans ; ensuite, elle continue à faire économiser.|5.000 ÷ 625 = 8 anys; després continua estalviant.", "80 years|80 años|80 ans|80 anys", "2 years|2 años|2 ans|2 anys", "Never|Nunca|Jamais|Mai"),
                    Q("savings", 3, "How long do solar panels usually last?|¿Cuánto suelen durar los paneles solares?|Combien de temps durent en général les panneaux solaires ?|Quant solen durar les plaques solars?", "About 25 years or more|Unos 25 años o más|Environ 25 ans ou plus|Uns 25 anys o més", "Manufacturers usually guarantee about 80 % of the power after 25 years.|Los fabricantes suelen garantizar en torno al 80 % de la potencia a los 25 años.|Les fabricants garantissent souvent environ 80 % de la puissance après 25 ans.|Els fabricants solen garantir al voltant del 80 % de la potència als 25 anys.", "1 year|1 año|1 an|1 any", "3 years|3 años|3 ans|3 anys", "200 years|200 años|200 ans|200 anys"),
                ]),
            new("trade-firstaid", "⛑️", "pink",
                Txt.Of("First aid|Primeros auxilios|Premiers secours|Primers auxilis"),
                Txt.Of("What to do in an emergency until help arrives: protect, alert, help; recovery position; bleeding and burns; choking; CPR.|Qué hacer ante una emergencia hasta que llega la ayuda: proteger, avisar, socorrer; posición lateral de seguridad; hemorragias y quemaduras; atragantamiento; RCP.|Que faire en cas d'urgence en attendant les secours : protéger, alerter, secourir ; position latérale de sécurité ; saignements et brûlures ; étouffement ; RCP.|Què fer davant d'una emergència fins que arriba l'ajuda: protegir, avisar, socórrer; posició lateral de seguretat; hemorràgies i cremades; ennuegament; RCP."),
                Txt.Of("This is an introduction: the best way to learn first aid is a practical course with a certified instructor. In an emergency call 112.|Esto es una introducción: la mejor forma de aprender primeros auxilios es un curso práctico con un instructor acreditado. En una emergencia, llama al 112.|Ceci est une introduction : la meilleure façon d'apprendre les premiers secours est une formation pratique avec un formateur agréé. En cas d'urgence, appelle le 112.|Això és una introducció: la millor manera d'aprendre primers auxilis és un curs pràctic amb un instructor acreditat. En una emergència, truca al 112."),
                [
                    C("pas", "Protect, alert, help|Proteger, avisar, socorrer|Protéger, alerter, secourir|Protegir, avisar, socórrer", "First make the place safe for you and the victim, then call 112 (where, what happened, how many people, how they are), then help.|Primero asegura el lugar para ti y la víctima, luego llama al 112 (dónde, qué ha pasado, cuántas personas, cómo están) y después socorre.|D'abord sécurise les lieux pour toi et la victime, puis appelle le 112 (où, que s'est-il passé, combien de personnes, dans quel état), puis secours.|Primer assegura el lloc per a tu i la víctima, després truca al 112 (on, què ha passat, quantes persones, com estan) i després socorre.", Area.Biology, "Biology: how the body reacts to an accident|Biología: cómo reacciona el cuerpo ante un accidente|Biologie : comment le corps réagit à un accident|Biologia: com reacciona el cos davant d'un accident"),
                    C("position", "Recovery position|Posición lateral de seguridad|Position latérale de sécurité|Posició lateral de seguretat", "An unconscious person who breathes normally is put on their side, head tilted back, so the tongue or vomit cannot block the airway.|A una persona inconsciente que respira con normalidad se la pone de lado, con la cabeza hacia atrás, para que la lengua o el vómito no tapen las vías respiratorias.|Une personne inconsciente qui respire normalement est mise sur le côté, la tête basculée en arrière, pour que la langue ou les vomissements ne bouchent pas les voies respiratoires.|A una persona inconscient que respira amb normalitat se la posa de costat, amb el cap enrere, perquè la llengua o el vòmit no tapin les vies respiratòries.", Area.Biology, "Biology: the airway and breathing|Biología: las vías respiratorias y la respiración|Biologie : les voies respiratoires et la respiration|Biologia: les vies respiratòries i la respiració", "pas"),
                    C("wounds", "Bleeding and burns|Hemorragias y quemaduras|Saignements et brûlures|Hemorràgies i cremades", "Press firmly on a bleeding wound with a clean cloth. Cool a burn under running water for about 20 minutes; no ice, butter or toothpaste.|Presiona con fuerza una herida que sangra con un paño limpio. Enfría una quemadura con agua corriente unos 20 minutos; nada de hielo, mantequilla ni pasta de dientes.|Appuie fort sur une plaie qui saigne avec un tissu propre. Refroidis une brûlure sous l'eau courante environ 20 minutes ; pas de glace, de beurre ni de dentifrice.|Pressiona amb força una ferida que sagna amb un drap net. Refreda una cremada amb aigua corrent uns 20 minuts; res de gel, mantega ni pasta de dents.", Area.Biology, "Biology: blood clotting and the skin|Biología: la coagulación y la piel|Biologie : la coagulation et la peau|Biologia: la coagulació i la pell", "pas"),
                    C("choking", "Choking|Atragantamiento|Étouffement|Ennuegament", "If the person can cough, encourage them to cough. If not: 5 firm blows between the shoulder blades, then 5 abdominal thrusts (Heimlich), and repeat.|Si la persona puede toser, anímala a toser. Si no: 5 golpes firmes entre los omóplatos y después 5 compresiones abdominales (Heimlich), y repetir.|Si la personne peut tousser, encourage-la à tousser. Sinon : 5 tapes fermes entre les omoplates, puis 5 compressions abdominales (Heimlich), et recommencer.|Si la persona pot tossir, anima-la a tossir. Si no: 5 cops ferms entre els omòplats i després 5 compressions abdominals (Heimlich), i repetir.", Area.Physics, "Physics: pressure in the lungs pushes the object out|Física: la presión en los pulmones empuja el objeto hacia fuera|Physique : la pression dans les poumons pousse l'objet dehors|Física: la pressió als pulmons empeny l'objecte cap a fora", "pas"),
                    C("cpr", "CPR|RCP|RCP|RCP", "If the person does not respond and does not breathe normally: call 112, push hard and fast in the centre of the chest (100–120 per minute, 5–6 cm), 30 compressions and 2 breaths, and use a defibrillator (AED) if there is one.|Si la persona no responde y no respira con normalidad: llama al 112, comprime fuerte y rápido en el centro del pecho (100–120 por minuto, 5–6 cm), 30 compresiones y 2 ventilaciones, y usa un desfibrilador (DEA) si lo hay.|Si la personne ne répond pas et ne respire pas normalement : appelle le 112, appuie fort et vite au centre de la poitrine (100–120 par minute, 5–6 cm), 30 compressions et 2 insufflations, et utilise un défibrillateur (DAE) s'il y en a un.|Si la persona no respon i no respira amb normalitat: truca al 112, comprimeix fort i ràpid al centre del pit (100–120 per minut, 5–6 cm), 30 compressions i 2 ventilacions, i fes servir un desfibril·lador (DEA) si n'hi ha.", Area.Biology, "Biology: the heart pumps blood and oxygen to the brain|Biología: el corazón bombea sangre y oxígeno al cerebro|Biologie : le cœur pompe le sang et l'oxygène vers le cerveau|Biologia: el cor bombeja sang i oxigen al cervell", "position"),
                ],
                [
                    Q("pas", 1, "What is the emergency number in the European Union?|¿Cuál es el número de emergencias en la Unión Europea?|Quel est le numéro d'urgence dans l'Union européenne ?|Quin és el número d'emergències a la Unió Europea?", "112", "112 works in every EU country, free, even without credit.|El 112 funciona en todos los países de la UE, gratis, incluso sin saldo.|Le 112 marche dans tous les pays de l'UE, gratuitement, même sans crédit.|El 112 funciona a tots els països de la UE, gratis, fins i tot sense saldo.", "911", "101", "999"),
                    Q("pas", 2, "You arrive at a road accident. What do you do first?|Llegas a un accidente de tráfico. ¿Qué haces primero?|Tu arrives sur un accident de la route. Que fais-tu d'abord ?|Arribes a un accident de trànsit. Què fas primer?", "Protect: make the place safe (warning signs, hazard lights)|Proteger: asegurar el lugar (señalizar, luces de emergencia)|Protéger : sécuriser les lieux (signaler, feux de détresse)|Protegir: assegurar el lloc (senyalitzar, llums d'emergència)", "If you get hurt you cannot help anyone: protect, then alert, then help.|Si tú te haces daño no puedes ayudar a nadie: proteger, avisar y después socorrer.|Si tu te blesses, tu ne peux aider personne : protéger, alerter, puis secourir.|Si tu et fas mal no pots ajudar ningú: protegir, avisar i després socórrer.", "Move the injured at once|Mover enseguida a los heridos|Déplacer tout de suite les blessés|Moure de seguida els ferits", "Give them water|Darles agua|Leur donner de l'eau|Donar-los aigua", "Take photos|Hacer fotos|Prendre des photos|Fer fotos"),
                    Q("pas", 3, "When you call 112, what must you say first?|Cuando llamas al 112, ¿qué debes decir primero?|Quand tu appelles le 112, que dois-tu dire d'abord ?|Quan truques al 112, què has de dir primer?", "Where you are|Dónde estás|Où tu es|On ets", "Without the place they cannot send help; then what happened and how many people. Do not hang up first.|Sin el lugar no pueden enviar ayuda; después qué ha pasado y cuántas personas. No cuelgues tú primero.|Sans le lieu, ils ne peuvent pas envoyer les secours ; ensuite ce qui s'est passé et combien de personnes. Ne raccroche pas le premier.|Sense el lloc no poden enviar ajuda; després què ha passat i quantes persones. No pengis tu primer.", "Your full name and age|Tu nombre completo y edad|Ton nom complet et ton âge|El teu nom complet i edat", "The colour of the car|El color del coche|La couleur de la voiture|El color del cotxe", "Nothing, just wait|Nada, solo esperar|Rien, juste attendre|Res, només esperar"),
                    Q("position", 1, "In which position do you place an unconscious person who breathes normally?|¿En qué posición pones a una persona inconsciente que respira con normalidad?|Dans quelle position places-tu une personne inconsciente qui respire normalement ?|En quina posició poses una persona inconscient que respira amb normalitat?", "On their side (recovery position)|De lado (posición lateral de seguridad)|Sur le côté (position latérale de sécurité)|De costat (posició lateral de seguretat)", "On the side, vomit comes out of the mouth instead of going into the lungs.|De lado, el vómito sale por la boca en lugar de ir a los pulmones.|Sur le côté, les vomissements sortent par la bouche au lieu d'aller dans les poumons.|De costat, el vòmit surt per la boca en lloc d'anar als pulmons.", "Sitting up|Sentada|Assise|Asseguda", "On their back with a pillow|Boca arriba con una almohada|Sur le dos avec un oreiller|Panxa enlaire amb un coixí", "Standing|De pie|Debout|Dreta"),
                    Q("position", 2, "Why is an unconscious person on their back in danger?|¿Por qué corre peligro una persona inconsciente boca arriba?|Pourquoi une personne inconsciente sur le dos est-elle en danger ?|Per què corre perill una persona inconscient panxa enlaire?", "The tongue or vomit can block the airway|La lengua o el vómito pueden tapar las vías respiratorias|La langue ou les vomissements peuvent boucher les voies respiratoires|La llengua o el vòmit poden tapar les vies respiratòries", "The muscles relax: the tongue falls back towards the throat.|Los músculos se relajan: la lengua cae hacia la garganta.|Les muscles se relâchent : la langue tombe vers la gorge.|Els músculs es relaxen: la llengua cau cap a la gola.", "They get cold|Se enfría|Elle a froid|Es refreda", "The heart stops at once|El corazón se para enseguida|Le cœur s'arrête tout de suite|El cor s'atura de seguida", "It is not dangerous|No es peligroso|Ce n'est pas dangereux|No és perillós"),
                    Q("position", 3, "You must check breathing: look, listen and feel for about…|Debes comprobar la respiración: mirar, escuchar y sentir durante unos…|Tu dois vérifier la respiration : regarder, écouter et sentir pendant environ…|Has de comprovar la respiració: mirar, escoltar i sentir durant uns…", "10 seconds|10 segundos|10 secondes|10 segons", "Head tilted back, chin up; no more than 10 s so as not to lose time.|Cabeza hacia atrás y mentón arriba; no más de 10 s para no perder tiempo.|Tête basculée en arrière, menton relevé ; pas plus de 10 s pour ne pas perdre de temps.|Cap enrere i barbeta amunt; no més de 10 s per no perdre temps.", "1 second|1 segundo|1 seconde|1 segon", "2 minutes|2 minutos|2 minutes|2 minuts", "10 minutes|10 minutos|10 minutes|10 minuts"),
                    Q("wounds", 1, "A wound is bleeding a lot. What do you do?|Una herida sangra mucho. ¿Qué haces?|Une plaie saigne beaucoup. Que fais-tu ?|Una ferida sagna molt. Què fas?", "Press firmly on it with a clean cloth|Presionar con fuerza con un paño limpio|Appuyer fort dessus avec un tissu propre|Pressionar amb força amb un drap net", "Direct pressure slows the bleeding and helps the blood clot.|La presión directa frena la hemorragia y ayuda a que la sangre coagule.|La pression directe freine le saignement et aide le sang à coaguler.|La pressió directa frena l'hemorràgia i ajuda que la sang coaguli.", "Wash it for a long time and wait|Lavarla mucho rato y esperar|La laver longtemps et attendre|Rentar-la molta estona i esperar", "Blow on it|Soplar|Souffler dessus|Bufar-hi", "Put butter on it|Ponerle mantequilla|Mettre du beurre|Posar-hi mantega"),
                    Q("wounds", 2, "How do you cool a burn?|¿Cómo se enfría una quemadura?|Comment refroidit-on une brûlure ?|Com es refreda una cremada?", "Under running water for about 20 minutes|Con agua corriente unos 20 minutos|Sous l'eau courante environ 20 minutes|Amb aigua corrent uns 20 minuts", "Lukewarm or cool running water stops the burn from going deeper and calms the pain.|El agua corriente templada o fresca impide que la quemadura profundice y calma el dolor.|L'eau courante tiède ou fraîche empêche la brûlure d'aller plus profond et calme la douleur.|L'aigua corrent tèbia o fresca impedeix que la cremada aprofundeixi i calma el dolor.", "With ice directly on the skin|Con hielo directamente en la piel|Avec de la glace directement sur la peau|Amb gel directament a la pell", "With toothpaste|Con pasta de dientes|Avec du dentifrice|Amb pasta de dents", "With butter or oil|Con mantequilla o aceite|Avec du beurre ou de l'huile|Amb mantega o oli"),
                    Q("wounds", 3, "A burn has formed a blister. What should you do with it?|Una quemadura ha hecho una ampolla. ¿Qué hay que hacer con ella?|Une brûlure a formé une cloque. Que faut-il en faire ?|Una cremada ha fet una butllofa. Què cal fer-ne?", "Do not burst it and cover it with a clean dressing|No reventarla y cubrirla con un apósito limpio|Ne pas la percer et la couvrir d'un pansement propre|No rebentar-la i cobrir-la amb un apòsit net", "The skin of the blister protects the wound from infection.|La piel de la ampolla protege la herida de infecciones.|La peau de la cloque protège la plaie des infections.|La pell de la butllofa protegeix la ferida d'infeccions.", "Burst it with a needle|Reventarla con una aguja|La percer avec une aiguille|Rebentar-la amb una agulla", "Pull off the skin|Quitar la piel|Arracher la peau|Treure la pell", "Put alcohol on it|Echarle alcohol|Mettre de l'alcool|Tirar-hi alcohol"),
                    Q("choking", 1, "Someone is choking but can cough strongly. What do you do?|Alguien se atraganta pero puede toser con fuerza. ¿Qué haces?|Quelqu'un s'étouffe mais peut tousser fort. Que fais-tu ?|Algú s'ennuega però pot tossir amb força. Què fas?", "Encourage them to keep coughing|Animarle a seguir tosiendo|L'encourager à continuer de tousser|Animar-lo a continuar tossint", "A strong cough is the best way to push the object out.|La tos fuerte es la mejor forma de expulsar el objeto.|Une toux forte est le meilleur moyen d'expulser l'objet.|La tos forta és la millor manera d'expulsar l'objecte.", "Give them water|Darle agua|Lui donner de l'eau|Donar-li aigua", "Lay them down|Tumbarle|L'allonger|Estirar-lo", "Hit them hard at once|Golpearle fuerte enseguida|Le taper fort tout de suite|Picar-lo fort de seguida"),
                    Q("choking", 2, "If the person can no longer cough or breathe, first give…|Si la persona ya no puede toser ni respirar, primero se dan…|Si la personne ne peut plus tousser ni respirer, on donne d'abord…|Si la persona ja no pot tossir ni respirar, primer es donen…", "5 blows between the shoulder blades|5 golpes entre los omóplatos|5 tapes entre les omoplates|5 cops entre els omòplats", "Lean them forward and strike with the heel of the hand; then 5 abdominal thrusts.|Inclínala hacia delante y golpea con el talón de la mano; después 5 compresiones abdominales.|Penche-la en avant et frappe avec le talon de la main ; puis 5 compressions abdominales.|Inclina-la endavant i colpeja amb el taló de la mà; després 5 compressions abdominals.", "a glass of water|un vaso de agua|un verre d'eau|un got d'aigua", "a piece of bread|un trozo de pan|un morceau de pain|un tros de pa", "nothing, wait|nada, esperar|rien, attendre|res, esperar"),
                    Q("choking", 3, "What does the Heimlich manoeuvre do?|¿Qué hace la maniobra de Heimlich?|Que fait la manœuvre de Heimlich ?|Què fa la maniobra de Heimlich?", "It pushes air out of the lungs to expel the object|Empuja el aire de los pulmones para expulsar el objeto|Elle pousse l'air hors des poumons pour expulser l'objet|Empeny l'aire dels pulmons per expulsar l'objecte", "Pressing up under the ribs raises the pressure in the chest, like an artificial cough.|Apretar hacia arriba bajo las costillas sube la presión en el pecho, como una tos artificial.|Appuyer vers le haut sous les côtes augmente la pression dans la poitrine, comme une toux artificielle.|Prémer cap amunt sota les costelles puja la pressió al pit, com una tos artificial.", "It restarts the heart|Reinicia el corazón|Elle relance le cœur|Reinicia el cor", "It makes the person sleep|Hace dormir a la persona|Elle fait dormir la personne|Fa dormir la persona", "It cools the throat|Enfría la garganta|Elle refroidit la gorge|Refreda la gola"),
                    Q("cpr", 1, "How many chest compressions per minute in CPR?|¿Cuántas compresiones torácicas por minuto en la RCP?|Combien de compressions thoraciques par minute en RCP ?|Quantes compressions toràciques per minut a la RCP?", "100 to 120|De 100 a 120|100 à 120|De 100 a 120", "About two per second: the rhythm of many well-known songs.|Unas dos por segundo: el ritmo de muchas canciones conocidas.|Environ deux par seconde : le rythme de beaucoup de chansons connues.|Unes dues per segon: el ritme de moltes cançons conegudes.", "10 to 20|De 10 a 20|10 à 20|De 10 a 20", "30 to 40|De 30 a 40|30 à 40|De 30 a 40", "200 to 300|De 200 a 300|200 à 300|De 200 a 300"),
                    Q("cpr", 2, "In adult CPR with breaths, the sequence is…|En la RCP de un adulto con ventilaciones, la secuencia es…|Dans la RCP d'un adulte avec insufflations, la séquence est…|A la RCP d'un adult amb ventilacions, la seqüència és…", "30 compressions and 2 breaths|30 compresiones y 2 ventilaciones|30 compressions et 2 insufflations|30 compressions i 2 ventilacions", "If you cannot or do not want to give breaths, do continuous compressions only.|Si no puedes o no quieres ventilar, haz solo compresiones continuas.|Si tu ne peux pas ou ne veux pas insuffler, fais seulement des compressions continues.|Si no pots o no vols ventilar, fes només compressions contínues.", "5 compressions and 5 breaths|5 compresiones y 5 ventilaciones|5 compressions et 5 insufflations|5 compressions i 5 ventilacions", "2 compressions and 30 breaths|2 compresiones y 30 ventilaciones|2 compressions et 30 insufflations|2 compressions i 30 ventilacions", "Only breaths|Solo ventilaciones|Seulement des insufflations|Només ventilacions"),
                    Q("cpr", 3, "What is an AED (automated external defibrillator) for?|¿Para qué sirve un DEA (desfibrilador externo automático)?|À quoi sert un DAE (défibrillateur automatisé externe) ?|Per a què serveix un DEA (desfibril·lador extern automàtic)?", "It gives an electric shock that can restore the heart rhythm|Da una descarga eléctrica que puede recuperar el ritmo del corazón|Il délivre un choc électrique qui peut rétablir le rythme du cœur|Fa una descàrrega elèctrica que pot recuperar el ritme del cor", "It speaks and guides you; it only shocks if it detects a rhythm that needs it.|Habla y te guía; solo da la descarga si detecta un ritmo que la necesita.|Il parle et te guide ; il ne délivre le choc que s'il détecte un rythme qui le nécessite.|Parla i et guia; només fa la descàrrega si detecta un ritme que la necessita.", "It measures the temperature|Mide la temperatura|Il mesure la température|Mesura la temperatura", "It gives oxygen|Da oxígeno|Il donne de l'oxygène|Dona oxigen", "It is only for doctors|Es solo para médicos|C'est seulement pour les médecins|És només per a metges"),
                ]),
            new("trade-cooking", "🧁", "peach",
                Txt.Of("Cooking and baking|Cocina y repostería|Cuisine et pâtisserie|Cuina i rebosteria"),
                Txt.Of("The science of the kitchen: heat and cooking, yeast and rising, emulsions, browning, and food safety.|La ciencia de la cocina: calor y cocción, levaduras y fermentación, emulsiones, dorado de los alimentos y seguridad alimentaria.|La science de la cuisine : chaleur et cuisson, levures et levée, émulsions, brunissement et sécurité alimentaire.|La ciència de la cuina: calor i cocció, llevats i fermentació, emulsions, daurat dels aliments i seguretat alimentària."),
                Txt.Of("Hot oil, ovens and knives are used with an adult.|El aceite caliente, el horno y los cuchillos se usan con un adulto.|L'huile chaude, le four et les couteaux s'utilisent avec un adulte.|L'oli calent, el forn i els ganivets es fan servir amb un adult."),
                [
                    C("heat", "Heat and cooking|Calor y cocción|Chaleur et cuisson|Calor i cocció", "Water boils at 100 °C at sea level and at less up a mountain; frying oil reaches 170–190 °C, so food browns and cooks faster.|El agua hierve a 100 °C al nivel del mar y a menos en la montaña; el aceite de freír llega a 170–190 °C, así que los alimentos se doran y cuecen antes.|L'eau bout à 100 °C au niveau de la mer et à moins en montagne ; l'huile de friture atteint 170–190 °C, donc les aliments dorent et cuisent plus vite.|L'aigua bull a 100 °C al nivell del mar i a menys a la muntanya; l'oli de fregir arriba a 170–190 °C, així que els aliments es dauren i es couen abans.", Area.Physics, "Physics: heat, temperature and boiling point|Física: calor, temperatura y punto de ebullición|Physique : chaleur, température et point d'ébullition|Física: calor, temperatura i punt d'ebullició"),
                    C("yeast", "Yeast and rising|Levadura y fermentación|Levure et levée|Llevat i fermentació", "Yeast is a living fungus: it eats sugar and gives off CO₂, which makes the dough rise. Baking powder makes CO₂ by a chemical reaction.|La levadura es un hongo vivo: come azúcar y suelta CO₂, que hace subir la masa. La levadura química produce CO₂ por una reacción química.|La levure est un champignon vivant : elle mange du sucre et dégage du CO₂, qui fait lever la pâte. La levure chimique produit du CO₂ par une réaction chimique.|El llevat és un fong viu: menja sucre i deixa anar CO₂, que fa pujar la massa. El llevat químic produeix CO₂ per una reacció química.", Area.Biology, "Biology: fermentation by microorganisms|Biología: la fermentación de los microorganismos|Biologie : la fermentation par les micro-organismes|Biologia: la fermentació dels microorganismes", "heat"),
                    C("emulsion", "Emulsions|Emulsiones|Émulsions|Emulsions", "Oil and water do not mix; an emulsifier like the lecithin of egg yolk holds tiny drops of oil in water, as in mayonnaise.|El aceite y el agua no se mezclan; un emulsionante como la lecitina de la yema mantiene gotitas de aceite en el agua, como en la mayonesa.|L'huile et l'eau ne se mélangent pas ; un émulsifiant comme la lécithine du jaune d'œuf garde de minuscules gouttes d'huile dans l'eau, comme dans la mayonnaise.|L'oli i l'aigua no es barregen; un emulsionant com la lecitina del rovell manté gotetes d'oli dins l'aigua, com a la maionesa.", Area.Chemistry, "Chemistry: mixtures and emulsifiers|Química: mezclas y emulsionantes|Chimie : mélanges et émulsifiants|Química: barreges i emulsionants", "heat"),
                    C("browning", "Browning: Maillard and caramel|Dorado: Maillard y caramelo|Brunissement : Maillard et caramel|Daurat: Maillard i caramel", "Above about 140 °C, proteins and sugars react (Maillard reaction) and give the crust of bread and the taste of grilled food; sugar alone caramelises.|Por encima de unos 140 °C, proteínas y azúcares reaccionan (reacción de Maillard) y dan la corteza del pan y el sabor de lo asado; el azúcar solo se carameliza.|Au-dessus d'environ 140 °C, protéines et sucres réagissent (réaction de Maillard) et donnent la croûte du pain et le goût du grillé ; le sucre seul caramélise.|Per sobre d'uns 140 °C, proteïnes i sucres reaccionen (reacció de Maillard) i donen la crosta del pa i el gust del rostit; el sucre sol es caramel·litza.", Area.Chemistry, "Chemistry: reactions that create flavour|Química: reacciones que crean sabor|Chimie : des réactions qui créent du goût|Química: reaccions que creen sabor", "yeast"),
                    C("safety", "Food safety|Seguridad alimentaria|Sécurité alimentaire|Seguretat alimentària", "Bacteria multiply fastest between about 5 and 60 °C: keep cold food in the fridge, cook well, wash your hands and do not mix raw and cooked food.|Las bacterias se multiplican más deprisa entre unos 5 y 60 °C: guarda en la nevera lo frío, cocina bien, lávate las manos y no mezcles lo crudo con lo cocinado.|Les bactéries se multiplient le plus vite entre environ 5 et 60 °C : garde le froid au réfrigérateur, cuis bien, lave-toi les mains et ne mélange pas le cru et le cuit.|Els bacteris es multipliquen més de pressa entre uns 5 i 60 °C: guarda a la nevera el que és fred, cuina bé, renta't les mans i no barregis el cru amb el cuinat.", Area.Biology, "Biology: bacteria and hygiene|Biología: bacterias e higiene|Biologie : bactéries et hygiène|Biologia: bacteris i higiene", "browning"),
                ],
                [
                    Q("heat", 1, "At what temperature does water boil at sea level?|¿A qué temperatura hierve el agua al nivel del mar?|À quelle température l'eau bout-elle au niveau de la mer ?|A quina temperatura bull l'aigua al nivell del mar?", "100 °C", "It is the boiling point of water at normal atmospheric pressure.|Es el punto de ebullición del agua a la presión atmosférica normal.|C'est le point d'ébullition de l'eau à la pression atmosphérique normale.|És el punt d'ebullició de l'aigua a la pressió atmosfèrica normal.", "50 °C", "180 °C", "0 °C"),
                    Q("heat", 2, "Why does pasta take longer to cook at the top of a high mountain?|¿Por qué tarda más en cocerse la pasta en lo alto de una montaña?|Pourquoi les pâtes cuisent-elles plus lentement en haute montagne ?|Per què triga més a coure's la pasta dalt d'una muntanya alta?", "Water boils below 100 °C because the air pressure is lower|El agua hierve por debajo de 100 °C porque la presión del aire es menor|L'eau bout en dessous de 100 °C car la pression de l'air est plus basse|L'aigua bull per sota de 100 °C perquè la pressió de l'aire és més baixa", "Boiling water is not as hot, so it cooks more slowly.|El agua hirviendo no está tan caliente y cuece más despacio.|L'eau bouillante est moins chaude, donc elle cuit plus lentement.|L'aigua bullint no és tan calenta i cou més a poc a poc.", "The water is colder up there|El agua de allí es más fría|L'eau là-haut est plus froide|L'aigua d'allà és més freda", "There is less oxygen in the pasta|Hay menos oxígeno en la pasta|Il y a moins d'oxygène dans les pâtes|Hi ha menys oxigen a la pasta", "It is not true|No es cierto|C'est faux|No és cert"),
                    Q("heat", 3, "Why does frying cook faster than boiling?|¿Por qué freír cocina más rápido que hervir?|Pourquoi la friture cuit-elle plus vite que l'ébullition ?|Per què fregir cou més ràpid que bullir?", "Oil can be much hotter than boiling water|El aceite puede estar mucho más caliente que el agua hirviendo|L'huile peut être beaucoup plus chaude que l'eau bouillante|L'oli pot estar molt més calent que l'aigua bullint", "Oil at 170–190 °C against water that stays at 100 °C.|Aceite a 170–190 °C frente a agua que se queda en 100 °C.|L'huile à 170–190 °C contre l'eau qui reste à 100 °C.|Oli a 170–190 °C davant d'aigua que es queda a 100 °C.", "Oil is lighter|El aceite es más ligero|L'huile est plus légère|L'oli és més lleuger", "Oil has more vitamins|El aceite tiene más vitaminas|L'huile a plus de vitamines|L'oli té més vitamines", "Water is wetter|El agua moja más|L'eau mouille plus|L'aigua mulla més"),
                    Q("yeast", 1, "What makes bread dough rise?|¿Qué hace subir la masa del pan?|Qu'est-ce qui fait lever la pâte à pain ?|Què fa pujar la massa del pa?", "CO₂ gas made by the yeast|El gas CO₂ que produce la levadura|Le gaz CO₂ produit par la levure|El gas CO₂ que produeix el llevat", "Yeast ferments the sugars; the gas bubbles stay trapped in the gluten.|La levadura fermenta los azúcares; las burbujas de gas quedan atrapadas en el gluten.|La levure fait fermenter les sucres ; les bulles de gaz restent piégées dans le gluten.|El llevat fermenta els sucres; les bombolles de gas queden atrapades al gluten.", "The salt|La sal|Le sel|La sal", "The oven light|La luz del horno|La lumière du four|La llum del forn", "The cold|El frío|Le froid|El fred"),
                    Q("yeast", 2, "What kind of living thing is baker's yeast?|¿Qué tipo de ser vivo es la levadura de panadería?|Quel type d'être vivant est la levure de boulanger ?|Quin tipus d'ésser viu és el llevat de forner?", "A fungus|Un hongo|Un champignon|Un fong", "It is a single-celled fungus (Saccharomyces cerevisiae).|Es un hongo unicelular (Saccharomyces cerevisiae).|C'est un champignon unicellulaire (Saccharomyces cerevisiae).|És un fong unicel·lular (Saccharomyces cerevisiae).", "A plant|Una planta|Une plante|Una planta", "An insect|Un insecto|Un insecte|Un insecte", "It is not alive|No está vivo|Ce n'est pas vivant|No és viu"),
                    Q("yeast", 3, "Why does very hot water spoil fresh yeast?|¿Por qué el agua muy caliente estropea la levadura fresca?|Pourquoi l'eau très chaude abîme-t-elle la levure fraîche ?|Per què l'aigua molt calenta fa malbé el llevat fresc?", "Above about 55–60 °C the yeast dies|Por encima de unos 55–60 °C la levadura muere|Au-dessus d'environ 55–60 °C la levure meurt|Per sobre d'uns 55–60 °C el llevat mor", "Lukewarm water (about 30–35 °C) wakes it up; too hot kills it.|El agua tibia (unos 30–35 °C) la despierta; demasiado caliente la mata.|L'eau tiède (environ 30–35 °C) la réveille ; trop chaude la tue.|L'aigua tèbia (uns 30–35 °C) el desperta; massa calenta el mata.", "It makes it rise too fast|La hace subir demasiado|Elle la fait trop lever|El fa pujar massa", "It turns it into salt|La convierte en sal|Elle la transforme en sel|El converteix en sal", "It does not spoil it|No la estropea|Elle ne l'abîme pas|No el fa malbé"),
                    Q("emulsion", 1, "Mayonnaise is a mixture of oil and…|La mayonesa es una mezcla de aceite y…|La mayonnaise est un mélange d'huile et…|La maionesa és una barreja d'oli i…", "egg yolk (with a little water or lemon)|yema de huevo (con un poco de agua o limón)|de jaune d'œuf (avec un peu d'eau ou de citron)|rovell d'ou (amb una mica d'aigua o llimona)", "The yolk holds millions of oil droplets dispersed in water.|La yema mantiene millones de gotitas de aceite repartidas en el agua.|Le jaune garde des millions de gouttelettes d'huile dispersées dans l'eau.|El rovell manté milions de gotetes d'oli repartides en l'aigua.", "flour|harina|de farine|farina", "sugar only|solo azúcar|de sucre seulement|només sucre", "salt only|solo sal|de sel seulement|només sal"),
                    Q("emulsion", 2, "What substance of the egg yolk lets oil and water mix?|¿Qué sustancia de la yema permite mezclar aceite y agua?|Quelle substance du jaune d'œuf permet de mélanger l'huile et l'eau ?|Quina substància del rovell permet barrejar oli i aigua?", "Lecithin, an emulsifier|La lecitina, un emulsionante|La lécithine, un émulsifiant|La lecitina, un emulsionant", "One end of the molecule likes water and the other likes oil.|Un extremo de la molécula se lleva bien con el agua y el otro con el aceite.|Un bout de la molécule aime l'eau et l'autre l'huile.|Un extrem de la molècula s'entén amb l'aigua i l'altre amb l'oli.", "Salt|La sal|Le sel|La sal", "Iron|El hierro|Le fer|El ferro", "Vitamin C|La vitamina C|La vitamine C|La vitamina C"),
                    Q("emulsion", 3, "A mayonnaise splits if you add the oil…|Una mayonesa se corta si añades el aceite…|Une mayonnaise tourne si tu ajoutes l'huile…|Una maionesa es talla si hi afegeixes l'oli…", "too fast, all at once|demasiado deprisa, de golpe|trop vite, d'un coup|massa de pressa, de cop", "The emulsifier needs time to coat each new drop of oil.|El emulsionante necesita tiempo para envolver cada gota nueva de aceite.|L'émulsifiant a besoin de temps pour envelopper chaque nouvelle goutte d'huile.|L'emulsionant necessita temps per embolcallar cada gota nova d'oli.", "drop by drop|gota a gota|goutte à goutte|gota a gota", "at room temperature|a temperatura ambiente|à température ambiante|a temperatura ambient", "while whisking|mientras bates|en fouettant|mentre bats"),
                    Q("browning", 1, "What gives toasted bread its golden colour and flavour?|¿Qué da su color dorado y su sabor al pan tostado?|Qu'est-ce qui donne au pain grillé sa couleur dorée et son goût ?|Què dona el color daurat i el gust al pa torrat?", "The Maillard reaction|La reacción de Maillard|La réaction de Maillard|La reacció de Maillard", "Proteins and sugars react with heat and create hundreds of flavours.|Proteínas y azúcares reaccionan con el calor y crean cientos de sabores.|Les protéines et les sucres réagissent à la chaleur et créent des centaines d'arômes.|Proteïnes i sucres reaccionen amb la calor i creen centenars de gustos.", "Mould|El moho|La moisissure|La floridura", "Salt melting|La sal que se derrite|Le sel qui fond|La sal que es fon", "Water evaporating only|Solo el agua que se evapora|Seulement l'eau qui s'évapore|Només l'aigua que s'evapora"),
                    Q("browning", 2, "Caramel is made by heating…|El caramelo se hace calentando…|Le caramel se fait en chauffant…|El caramel es fa escalfant…", "sugar|azúcar|du sucre|sucre", "Sugar molecules break and form new brown, aromatic compounds.|Las moléculas de azúcar se rompen y forman compuestos nuevos, marrones y aromáticos.|Les molécules de sucre se cassent et forment de nouveaux composés bruns et aromatiques.|Les molècules de sucre es trenquen i formen compostos nous, marrons i aromàtics.", "salt|sal|du sel|sal", "flour|harina|de la farine|farina", "water alone|solo agua|de l'eau seule|només aigua"),
                    Q("browning", 3, "Why does meat cooked in boiling water not brown?|¿Por qué la carne cocida en agua no se dora?|Pourquoi la viande cuite dans l'eau ne dore-t-elle pas ?|Per què la carn bullida no es daura?", "Water stays at 100 °C, below the temperature of browning|El agua se queda en 100 °C, por debajo de la temperatura del dorado|L'eau reste à 100 °C, sous la température du brunissement|L'aigua es queda a 100 °C, per sota de la temperatura del daurat", "Browning needs a dry surface above about 140 °C (grill, pan, oven).|El dorado necesita una superficie seca por encima de unos 140 °C (plancha, sartén, horno).|Le brunissement demande une surface sèche au-dessus d'environ 140 °C (grill, poêle, four).|El daurat necessita una superfície seca per sobre d'uns 140 °C (planxa, paella, forn).", "Water removes the proteins|El agua quita las proteínas|L'eau enlève les protéines|L'aigua treu les proteïnes", "Meat cannot brown|La carne no puede dorarse|La viande ne peut pas dorer|La carn no es pot daurar", "The pot is too big|La olla es demasiado grande|La casserole est trop grande|L'olla és massa gran"),
                    Q("safety", 1, "What should you always do before cooking?|¿Qué hay que hacer siempre antes de cocinar?|Que faut-il toujours faire avant de cuisiner ?|Què cal fer sempre abans de cuinar?", "Wash your hands with soap|Lavarse las manos con jabón|Se laver les mains au savon|Rentar-se les mans amb sabó", "Hands carry bacteria to the food.|Las manos llevan bacterias a los alimentos.|Les mains transportent des bactéries vers les aliments.|Les mans porten bacteris als aliments.", "Open the window|Abrir la ventana|Ouvrir la fenêtre|Obrir la finestra", "Switch on the radio|Encender la radio|Allumer la radio|Encendre la ràdio", "Nothing special|Nada especial|Rien de spécial|Res d'especial"),
                    Q("safety", 2, "Between which temperatures do bacteria multiply fastest in food?|¿Entre qué temperaturas se multiplican más deprisa las bacterias en los alimentos?|Entre quelles températures les bactéries se multiplient-elles le plus vite dans les aliments ?|Entre quines temperatures es multipliquen més de pressa els bacteris en els aliments?", "About 5 °C to 60 °C|Entre unos 5 °C y 60 °C|Entre environ 5 °C et 60 °C|Entre uns 5 °C i 60 °C", "That is why leftovers go into the fridge quickly and food is reheated well.|Por eso las sobras van rápido a la nevera y la comida se recalienta bien.|C'est pourquoi les restes vont vite au frigo et qu'on réchauffe bien.|Per això les restes van ràpid a la nevera i el menjar es reescalfa bé.", "−20 °C → −10 °C", "100 °C → 200 °C", "Only above 100 °C|Solo por encima de 100 °C|Seulement au-dessus de 100 °C|Només per sobre de 100 °C"),
                    Q("safety", 3, "Why do you use a different board for raw chicken and for salad?|¿Por qué se usa una tabla distinta para el pollo crudo y para la ensalada?|Pourquoi utiliser une planche différente pour le poulet cru et pour la salade ?|Per què es fa servir una taula diferent per al pollastre cru i per a l'amanida?", "To avoid cross-contamination: raw chicken can carry bacteria like Salmonella|Para evitar la contaminación cruzada: el pollo crudo puede llevar bacterias como la salmonela|Pour éviter la contamination croisée : le poulet cru peut porter des bactéries comme la salmonelle|Per evitar la contaminació creuada: el pollastre cru pot portar bacteris com la salmonel·la", "The salad will not be cooked, so its bacteria would not be killed.|La ensalada no se cocina, así que esas bacterias no morirían.|La salade ne sera pas cuite, donc ces bactéries ne seraient pas tuées.|L'amanida no es cuina, així que aquests bacteris no moririen.", "For the colour|Por el color|Pour la couleur|Pel color", "Chicken blunts knives|El pollo desafila los cuchillos|Le poulet émousse les couteaux|El pollastre desafila els ganivets", "It is only tradition|Es solo tradición|C'est seulement une tradition|És només tradició"),
                ]),
        ];
    }
}
